@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="page-btn"
                disabled="@(Page <= 1)"
                @onclick="@(() => OnPageChanged.InvokeAsync(Page - 1))">
            Previous
        </button>

        @foreach (var pageNum in PageNumbers)
        {
            <button class="@PageButtonClass(pageNum)"
                    @onclick="@(() => OnPageChanged.InvokeAsync(pageNum))">
                @pageNum
            </button>
        }

        <button class="page-btn"
                disabled="@(Page >= TotalPages)"
                @onclick="@(() => OnPageChanged.InvokeAsync(Page + 1))">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private IEnumerable<int> PageNumbers => Enumerable.Range(1, TotalPages);

    private string PageButtonClass(int pageNum) =>
        pageNum == Page ? "page-btn active" : "page-btn";
}

.catalog-pagination {
    display: flex;
    justify-content: center;
