    padding: 0.4rem 0.8rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    color: #0d6efd;
}

.page-btn:hover:not(:disabled):not(.active) {
    background: #e9ecef;
}

